// Generated by scripts/matrix.ts (ADR 0182): each string method on each string, and each pair of them, where text goes wrong. Edit it there.

// Each result by `{:?}`, which escapes as Rust's `Debug` does: a control
// character, a quote, a backslash, a character Unicode says to escape.

const STRINGS: &[&str] = &[
    "",
    "a",
    "ab",
    "abc",
    "A",
    " ",
    "a b",
    "a,b,,c",
    "\t\r\n",
    "line\nnext\r\nlast",
    "\0",
    "a\0b",
    "\"'\\<>&-->",
    "\u{00e9}",
    "e\u{0301}",
    "\u{00df}",
    "\u{0130}",
    "\u{01c5}",
    "\u{1f980}",
    "\u{e000}",
    "\u{10ffff}",
    "\u{0085}hello\u{0085}",
    "\u{feff}hello\u{feff}",
    "\u{2028}\u{2029}",
    "\u{200b}",
    "\u{00a0} hello \u{3000}",
    "\u{7f}\u{9f}",
    "-12",
    "+3.5e2",
    "1_000",
];

// The semantics page's listed differences, found exactly on both sides, by
// numbers: strings compare by UTF-16 units, and `trim()` uses JS's
// whitespace. Where one shows, the line says "listed".

fn units(s: &str) -> Vec<u32> {
    let mut out = Vec::new();
    for c in s.chars() {
        let c = c as u32;
        if c > 0xffff {
            out.push(0xd800 + ((c - 0x10000) >> 10));
            out.push(0xdc00 + (c & 0x3ff));
        } else {
            out.push(c);
        }
    }
    out
}

fn order_listed(a: &str, b: &str) -> bool {
    let points = |s: &str| s.chars().map(|c| c as u32).collect::<Vec<u32>>();
    points(a).cmp(&points(b)) != units(a).cmp(&units(b))
}

fn trim_listed(a: &str) -> bool {
    a.contains('\u{85}') || a.contains('\u{feff}')
}

fn main() {
    for &a in STRINGS {
        println!(
            "{a:?}: len {} {} {} chars {:?} rev {:?} case {:?} {:?} {:?} {:?}",
            a.len(),
            a.is_empty(),
            a.chars().count(),
            a.chars().nth(1),
            a.chars().rev().collect::<String>(),
            a.to_uppercase(),
            a.to_lowercase(),
            a.to_ascii_uppercase(),
            a.to_ascii_lowercase(),
        );
        let trims = match trim_listed(a) {
            true => "listed".to_string(),
            false => format!("{:?} {:?} {:?}", a.trim(), a.trim_start(), a.trim_end()),
        };
        println!(
            "{a:?}: trim {trims} {:?} {:?} words {:?} lines {:?}",
            a.trim_matches(' '),
            a.trim_start_matches('a'),
            a.split_whitespace().collect::<Vec<_>>(),
            a.lines().collect::<Vec<_>>(),
        );
        println!(
            "{a:?}: split {:?} {:?} {:?} {:?} bytes {} {:?} {} {:?} {:?}",
            a.split(',').collect::<Vec<_>>(),
            a.splitn(2, ' ').collect::<Vec<_>>(),
            a.rsplit(' ').collect::<Vec<_>>(),
            a.split_once(','),
            a.bytes().map(u32::from).sum::<u32>(),
            a.char_indices().collect::<Vec<_>>(),
            a.is_char_boundary(1),
            a.get(0..1),
            a.char_indices().rev().next(),
        );
        println!(
            "{a:?}: find {:?} {:?} {:?} {} replace {:?} {:?} fmt [{:>8}] [{:<8}] [{:^8}] [{:.2}] parse {:?} {:?} lossy {:?} all {}",
            a.find('a'),
            a.rfind('a'),
            a.find("b"),
            a.matches('a').count(),
            a.replace("a", "xy"),
            a.repeat(2),
            a,
            a,
            a,
            a,
            a.parse::<i32>(),
            a.parse::<f64>(),
            String::from_utf8_lossy(a.as_bytes()),
            a.chars().all(char::is_whitespace),
        );
        for &b in STRINGS {
            let order = match order_listed(a, b) {
                true => "listed".to_string(),
                false => format!("{:?} {}", a.cmp(b), a < b),
            };
            println!(
                "{a:?} {b:?}: {} {} {} {order} {} {} {:?} {:?} {:?} {}",
                a.starts_with(b),
                a.ends_with(b),
                a.contains(b),
                a == b,
                a.eq_ignore_ascii_case(b),
                a.find(b),
                a.strip_prefix(b),
                a.strip_suffix(b),
                format!("{a}{b}").len(),
            );
        }
    }
}
